#define MAHJONGG_GNOME_LAYOUTS_H

struct mj_gnome_slot {
    short x;
    short y;
    short layer;
};

struct mj_gnome_layout {
    const char *name;
    const char *score_name;
    int slot_count;
    const struct mj_gnome_slot *slots;
};

